   264:        imu_i2c_read_regs(0x0015, gyro_raw_z, 2);
   265:        imu_i2c_read_regs(0x0009, temp_raw, 2);
   266:
   267:        accel_x = (float)(*((int16_t *)accel_raw_x)) / 16384.0;
   268:        accel_y = (float)(*((int16_t *)accel_raw_y)) / 16384.0;
