   305:            printf("temp:  %+0.3f °C\n", temp);
   306:            tft_refresh();
   307:        }
   308:        break;
   309:        case KEY2_CODE:
   310:        {
   311:            snprintf(buff, 40, "gyro: x:%+08.3f LSB\n", gyro_x);
   312:            tft_show_string(0, 0, buff, 0xFFFF, 0x0000, 16, 1);
   313:            printf("%s", buff);
   314:            snprintf(buff, 40, "      y:%+08.3f LSB\n", gyro_y);
   315:            tft_show_string(0, 20, buff, 0xFFFF, 0x0000, 16, 1);
   316:            printf("%s", buff);
   317:            snprintf(buff, 40, "      z:%+08.3f LSB\n", gyro_z);
   318:            tft_show_string(0, 40, buff, 0xFFFF, 0x0000, 16, 1);
   319:            printf("%s", buff);
   320:            snprintf(buff, 40, "temp: %+f\n", temp);
   321:            tft_show_string(0, 60, buff, 0xFFFF, 0x0000, 16, 1);
   322:            printf("temp:  %+0.3f °C\n", temp);
   323:            tft_refresh();
   324:        }
   325:        break;
   326:        case KEY3_CODE:
   327:            return;
   328:        default:
