    50:static int g_i2c_fd;
    51:static inline int imu_switch_on_mclk(void)
    52:{
    53:    uint8_t buf;
    54:    imu_i2c_read_regs(0x1F, &buf, 1);
    55:    if (!(buf & 0x10))
    56:    {
    57:        uint32_t timeout = 0;
    58:        buf |= 0x10;
    59:        imu_i2c_write_regs(0x1F, &buf, 1);
    60:
    61:        do
    62:        {
    63:            imu_i2c_read_regs(0x00, &buf, 1);
    64:            timeout ++;
    65:            if (timeout > 0xFFFFFFFE)
    66:            {
    67:                printf("imu switch on mclk timeout\n");
    68:                exit(-1);
    69:            }
    70:        }
    71:        while (!(buf & 0x08));
    72:    }
    73:    return 0;
    74:}
    75:
    76:static inline int imu_switch_off_mclk(void)
    77:{
    78:    uint8_t buf;
    79:    imu_i2c_read_regs(0x1F, &buf, 1);
    80:    if (buf & 0x10)
    81:    {
    82:        buf &= ~0x10;
    83:        imu_i2c_write_regs(0x1F, &buf, 1);
    84:    }
    85:    return 0;
    86:}
    87:
    88:int imu_i2c_write_regs(uint16_t reg, uint8_t *buf, uint8_t len)
    89:{
    90:    if (reg & 0xFF00)
    91:    {
    92:        uint8_t w_buf;
    93:        uint8_t blk_sel = (reg & 0xFF00) >> 8;
    94:        if (blk_sel == 0x10)
    95:        {
    96:            blk_sel = 0x00;
    97:        }
    98:        if (imu_switch_on_mclk() == -1)
    99:        {
   100:            return  -1;
   101:        }
   102:        if (blk_sel)
   103:        {
   104:            w_buf = blk_sel;
   105:            imu_i2c_write_regs(0x79, &w_buf, 1);
   106:        }
   107:        w_buf = reg & 0x00FF;
   108:        imu_i2c_write_regs(0x7A, &w_buf, 1);
   109:        for (uint8_t i = 0; i < len; i++)
   110:        {
   111:            w_buf = buf[i];
   112:            imu_i2c_write_regs(0x7B, &w_buf, 1);
   113:        }
   114:        if (blk_sel)
   115:        {
   116:            w_buf = 0x00;
   117:            imu_i2c_write_regs(0x79, &w_buf, 1);
   118:        }
   119:
   120:        imu_switch_off_mclk();
   121:    }
   122:    else
   123:    {
   124:        uint8_t *tmp = (uint8_t *)calloc(len + 1, sizeof(uint8_t));
   125:        if (tmp == NULL)
   126:        {
   127:            printf("malloc i2c buff fail\n");
   128:            exit(-1);
   129:        }
   130:        tmp[0] = (uint8_t)reg;
   131:        memcpy(&tmp[1], buf, len);
   132:        if (write(g_i2c_fd, tmp, len + 1) != len + 1)
   133:        {
   134:            printf("i2c write error\n");
   135:            exit(-1);
   136:        }
   137:        free(tmp);
   138:    }
   139:    return 0;
   140:}
   141:
   142:int imu_i2c_read_regs(uint16_t reg, uint8_t *buf, uint8_t len)
   143:{
   144:    if (reg & 0xFF00)
   145:    {
   146:        if (imu_switch_on_mclk() == -1)
   147:        {
   148:            return  -1;
   149:        }
   150:        for (uint8_t i = 0; i < len; i++)
   151:        {
   152:            uint8_t r_buf;
   153:            uint16_t reg_addr = (reg + i) & 0xFF00;
   154:            uint8_t blk_sel = reg_addr >> 8;
   155:            if (blk_sel == 0x10)
   156:            {
   157:                blk_sel = 0x00;
   158:            }
   159:
   160:            if (blk_sel)
   161:            {
   162:                imu_i2c_write_regs(0x7C, &blk_sel, 1);
   163:            }
   164:            r_buf = reg_addr & 0x00FF;
   165:            imu_i2c_write_regs(0x7D, &r_buf, 1);
   166:            imu_i2c_read_regs(0x7E, &buf[i], 1);
   167:            if (blk_sel)
   168:            {
   169:                r_buf = 0x00;
   170:                imu_i2c_write_regs(0x7C, &r_buf, 1);
   171:            }
   172:        }
   173:
   174:        imu_switch_off_mclk();
   175:    }
   176:    else
   177:    {
   178:        if (write(g_i2c_fd, &reg, 1) != 1)
   179:        {
   180:            printf("i2c write error\n");
   181:            exit(-1);
   182:        }
   183:        if (read(g_i2c_fd, buf, len) != len)
   184:        {
   185:            printf("i2c read error\n");
   186:            exit(-1);
   187:        }
   188:    }
   189:
   190:    return 0;
   191:}
   192:
   193:int imu_init(void)
   194:{
   195:    uint8_t reg;
   196:    uint8_t buf;
   197:    g_i2c_fd = open(IMU_I2C, O_RDWR);
   198:    if (g_i2c_fd <= 0)
   199:    {
   200:        printf("open %s failed\n", IMU_I2C);
   201:        exit(-1);
   202:    }
   203:    if (ioctl(g_i2c_fd, I2C_SLAVE, IMU_I2C_ADDR) < 0)
   204:    {
   205:        printf("i2c ioctl error");
   206:        exit(-1);
   207:    }
   208:    reg = 0x75;
   209:    imu_i2c_read_regs(reg, &buf, 1);
   210:    if (buf != IMU_WHOAMI)
   211:    {
   212:        printf("get WHOAMI faild: 0x%02X\n", buf);
   213:        exit(-1);
   214:    }
   215:
   216:    buf = 0x41;
   217:    imu_i2c_write_regs(0x36, &buf, 1);
   218:
   219:    buf = 0xB0;
   220:    imu_i2c_write_regs(0x35, &buf, 1);
   221:
   222:    usleep(3000);
   223:    buf = 0x10;
   224:    imu_i2c_write_regs(0x02, &buf, 1);
   225:    buf = 0x41;
   226:    imu_i2c_write_regs(0x36, &buf, 1);
   227:
   228:    buf = 0xB0;
   229:    imu_i2c_write_regs(0x35, &buf, 1);
   230:    usleep(1000);
   231:
   232:    imu_i2c_read_regs(0x35, &buf, 1);
   233:    buf &= ~0x10;
   234:    imu_i2c_write_regs(0x35, &buf, 1);
   235:    imu_i2c_read_regs(0x3A, &buf, 1);
   236:    if (!(buf & 0x10))
   237:    {
   238:        printf("soft reset faild\n");
   239:        exit(-1);
   240:    }
   241:
   242:    buf = 0x66;
   243:    imu_i2c_write_regs(0x21, &buf, 1);
   244:
   245:    buf = 0x66;
   246:    imu_i2c_write_regs(0x20, &buf, 1);
   247:
   248:    buf = 0x30;
   249:    imu_i2c_write_regs(0x22, &buf, 1);
   250:
   251:    buf = 0x03;
   252:    imu_i2c_write_regs(0x06, &buf, 1);
   253:
   254:    imu_switch_on_mclk();
   255:    buf = 0x00;
   256:    imu_i2c_write_regs(0x1001, &buf, 1);
   257:    imu_switch_off_mclk();
   258:    imu_i2c_read_regs(0x1F, &buf, 1);
   259:    buf |= 0x8F;
