        if sub == 0:
            extra += '｜⚠ /goal_pose 没有订阅者（先跑 nav --listen）'
        msg = '目标已设：x=%.2f y=%.2f%s' % (x, y, extra)
        self.get_logger().info(msg)
        return {'ok': True, 'msg': msg, 'x': round(x, 2), 'y': round(y, 2), 'sub': sub}
