function panBy(dxScreen, dyScreen){
  const r=mimg.getBoundingClientRect(); const sz=mimg.naturalWidth||480;
  const sc=Math.min(r.width/sz, r.height/sz)||1;
  const mPerScreenPx = (view.range/sz)/sc;
  view.dx -= dxScreen*mPerScreenPx;
  view.dy += dyScreen*mPerScreenPx;      // 屏幕 y 向下；世界 y 向上
}
